/* The BIOS's text fonts and the VGA's palettes (vgadata.c, generated by tools/gen_qbvga.py). */
#ifndef QB_VGADATA_H
#define QB_VGADATA_H

/* 256 characters of 8, 14 or 16 rows, one byte a row. */
extern const unsigned char qb_vga_font_8[256 * 8];
extern const unsigned char qb_vga_font_14[256 * 14];
extern const unsigned char qb_vga_font_16[256 * 16];
/* The 64 colours of the EGA (the number is the bits r g b R G B), and the VGA's default 256, as red, green and blue of 0 to 63. */
extern const unsigned char qb_ega_palette[64][3];
extern const unsigned char qb_vga_palette[256][3];

#endif
